<!-- Scripts -->
<script src="<?php echo $path_theme; ?>assets/js/bmpn/bpmn-modeler.min.js"></script>
<script src="<?php echo $path_theme; ?>assets/js/bmpn/diagram-grid.umd.prod.js"></script>
<script src="<?php echo $path_theme; ?>assets/js/bmpn/color-picker-module.js"></script>

<script>
    // Variables globales
    let modeler;
    let currentProcessId = null;
    let currentTaskId = null;

    // Inicialización
    document.addEventListener('DOMContentLoaded', function() {
        initializeBpmnModeler();
        loadProcesses();
        loadTasks();
        loadMetrics();

        // Actualizar tareas cada 30 segundos
        setInterval(loadTasks, 30000);
    });

    function initializeBpmnModeler() {
        modeler = new BpmnJS({
            container: '#canvas',
            keyboard: {
                bindTo: window
            }
        });

        // Cargar diagrama vacío
        newDiagram();

        // Eventos del modelador
        modeler.on('element.dblclick', function(event) {
            const element = event.element;
            if (element.type === 'bpmn:UserTask') {
                showTaskConfiguration(element);
            }
        });
    }

    function newDiagram() {
        const emptyBpmn = `<?php echo '<?xml'; ?> version="1.0" encoding="UTF-8"?>
        <bpmn2:definitions xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" 
                            xmlns:bpmn2="http://www.omg.org/spec/BPMN/20100524/MODEL" 
                            xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" 
                            xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" 
                            xsi:schemaLocation="http://www.omg.org/spec/BPMN/20100524/MODEL BPMN20.xsd" 
                            id="sample-diagram" 
                            targetNamespace="http://bpmn.io/schema/bpmn">
            <bpmn2:process id="Process_1" isExecutable="true">
            <bpmn2:startEvent id="StartEvent_1" name="Inicio"/>
            </bpmn2:process>
            <bpmndi:BPMNDiagram id="BPMNDiagram_1">
            <bpmndi:BPMNPlane id="BPMNPlane_1" bpmnElement="Process_1">
                <bpmndi:BPMNShape id="_BPMNShape_StartEvent_2" bpmnElement="StartEvent_1">
                <dc:Bounds height="36.0" width="36.0" x="412.0" y="240.0"/>
                </bpmndi:BPMNShape>
            </bpmndi:BPMNPlane>
            </bpmndi:BPMNDiagram>
        </bpmn2:definitions>`;

        modeler.importXML(emptyBpmn);
        currentProcessId = null;
    }

    async function saveDiagram() {
        try {
            const {
                xml
            } = await modeler.saveXML({
                format: true
            });

            if (!currentProcessId) {
                showCreateProcessModal();
                return;
            }

            const response = await fetch('/api/processes/' + currentProcessId, {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    bpmn_xml: xml
                })
            });

            const result = await response.json();

            if (result.success) {
                showNotification('Proceso guardado correctamente', 'success');
            } else {
                throw new Error(result.error);
            }

        } catch (error) {
            showNotification('Error al guardar: ' + error.message, 'error');
        }
    }

    async function loadProcesses() {
        try {
            const response = await fetch('/api/processes');
            const data = await response.json();

            const processList = document.getElementById('processList');
            processList.innerHTML = '';

            if (data.processes.length === 0) {
                processList.innerHTML = '<div style="text-align: center; color: #666;">No hay procesos</div>';
                return;
            }

            data.processes.forEach(process => {
                const div = document.createElement('div');
                div.className = 'process-item';
                div.onclick = () => loadProcess(process.id);

                div.innerHTML = `
                    <div class="process-name" style="font-weight: 600;">${process.name}</div>
                    <div class="process-info" style="font-size: 12px; color: #666;">
                        Versión ${process.version} • 
                        <span class="status-badge ${process.is_active ? 'status-running' : 'status-failed'}">
                            ${process.is_active ? 'Activo' : 'Inactivo'}
                        </span>
                    </div>
                `;

                processList.appendChild(div);
            });

        } catch (error) {
            document.getElementById('processList').innerHTML =
                '<div style="color: #dc3545;">Error al cargar procesos</div>';
        }
    }

    async function loadProcess(processId) {
        try {
            const response = await fetch('/api/processes/' + processId);
            const data = await response.json();

            if (data.bpmn_xml) {
                await modeler.importXML(data.bpmn_xml);
                currentProcessId = processId;

                // Marcar como activo en la lista
                document.querySelectorAll('.process-item').forEach(item => {
                    item.classList.remove('active');
                });
                event.currentTarget.classList.add('active');

                showNotification('Proceso cargado correctamente', 'success');
                loadMetrics(processId);
            }

        } catch (error) {
            showNotification('Error al cargar proceso: ' + error.message, 'error');
        }
    }

    async function loadTasks() {
        try {
            const response = await fetch('/api/tasks?scope=my&status=assigned');
            const data = await response.json();

            const taskList = document.getElementById('taskList');
            taskList.innerHTML = '';

            if (data.tasks.length === 0) {
                taskList.innerHTML = '<div style="text-align: center; color: #666;">No hay tareas pendientes</div>';
                return;
            }

            data.tasks.forEach(task => {
                const div = document.createElement('div');
                div.className = 'task-item';

                // Determinar clase según prioridad y fecha límite
                if (task.due_date && new Date(task.due_date) < new Date()) {
                    div.classList.add('overdue');
                } else if (task.priority > 7) {
                    div.classList.add('high-priority');
                }

                div.onclick = () => openTask(task);

                const dueDate = task.due_date ?
                    new Date(task.due_date).toLocaleDateString('es-ES') : 'Sin límite';

                div.innerHTML = `
                    <div class="task-name">${task.task_name}</div>
                    <div class="task-info">
                        ${task.workflow_instance.process_name}<br>
                        Vence: ${dueDate}
                    </div>
                `;

                taskList.appendChild(div);
            });

        } catch (error) {
            document.getElementById('taskList').innerHTML =
                '<div style="color: #dc3545;">Error al cargar tareas</div>';
        }
    }

    async function loadMetrics(processId = null) {
        try {
            let url = '/api/metrics';
            if (processId) {
                url += '/' + processId;
            }

            const response = await fetch(url);
            const data = await response.json();

            const metricsGrid = document.getElementById('metricsGrid');
            metricsGrid.innerHTML = '';

            if (data.summary) {
                const metrics = [{
                        label: 'Iniciados',
                        value: data.summary.total_started,
                        icon: 'fa-play'
                    },
                    {
                        label: 'Completados',
                        value: data.summary.total_completed,
                        icon: 'fa-check'
                    },
                    {
                        label: 'Fallidos',
                        value: data.summary.total_failed,
                        icon: 'fa-times'
                    },
                    {
                        label: 'Tasa Éxito',
                        value: data.summary.completion_rate.toFixed(1) + '%',
                        icon: 'fa-percentage'
                    }
                ];

                metrics.forEach(metric => {
                    const div = document.createElement('div');
                    div.className = 'metric-card';
                    div.innerHTML = `
                        <div class="metric-value">${metric.value}</div>
                        <div class="metric-label"><i class="fas ${metric.icon}"></i> ${metric.label}</div>
                    `;
                    metricsGrid.appendChild(div);
                });
            } else {
                metricsGrid.innerHTML = '<div style="text-align: center; color: #666;">No hay métricas disponibles</div>';
            }

        } catch (error) {
            document.getElementById('metricsGrid').innerHTML =
                '<div style="color: #dc3545;">Error al cargar métricas</div>';
        }
    }

    function showCreateProcessModal() {
        document.getElementById('createProcessModal').classList.add('active');
    }

    function deployProcess() {
        if (!currentProcessId) {
            showNotification('Seleccione un proceso primero', 'warning');
            return;
        }
        document.getElementById('deployModal').classList.add('active');
    }

    function runSimulation() {
        if (!currentProcessId) {
            showNotification('Seleccione un proceso primero', 'warning');
            return;
        }
        document.getElementById('simulationModal').classList.add('active');
    }

    function openTask(task) {
        currentTaskId = task.id;
        document.getElementById('taskModalTitle').textContent = `Completar: ${task.task_name}`;

        // Generar campos de formulario dinámicos
        const formFields = document.getElementById('taskFormFields');
        formFields.innerHTML = '';

        if (task.form_data && task.form_data.fields) {
            task.form_data.fields.forEach(field => {
                const div = document.createElement('div');
                div.className = 'form-group';

                let input = '';
                switch (field.type) {
                    case 'text':
                        input = `<input type="text" name="${field.name}" ${field.required ? 'required' : ''}>`;
                        break;
                    case 'number':
                        input = `<input type="number" name="${field.name}" ${field.required ? 'required' : ''}>`;
                        break;
                    case 'select':
                        const options = field.options.map(opt => `<option value="${opt.value}">${opt.label}</option>`).join('');
                        input = `<select name="${field.name}" ${field.required ? 'required' : ''}>${options}</select>`;
                        break;
                    case 'textarea':
                        input = `<textarea name="${field.name}" rows="3" ${field.required ? 'required' : ''}></textarea>`;
                        break;
                }

                div.innerHTML = `
                    <label>${field.label}:</label>
                    ${input}
                `;
                formFields.appendChild(div);
            });
        }

        document.getElementById('taskModal').classList.add('active');
    }

    function closeModal(modalId) {
        document.getElementById(modalId).classList.remove('active');
    }

    function showNotification(message, type = 'info') {
        const notification = document.getElementById('notification');
        notification.textContent = message;
        notification.className = `notification ${type}`;
        notification.classList.add('show');

        setTimeout(() => {
            notification.classList.remove('show');
        }, 3000);
    }

    // Formularios
    document.getElementById('createProcessForm').onsubmit = async function(e) {
        e.preventDefault();

        try {
            const {
                xml
            } = await modeler.saveXML({
                format: true
            });

            const response = await fetch('/api/processes', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    name: document.getElementById('processName').value,
                    description: document.getElementById('processDescription').value,
                    bpmn_xml: xml
                })
            });

            const result = await response.json();

            if (result.success) {
                currentProcessId = result.process_id;
                showNotification('Proceso creado correctamente', 'success');
                closeModal('createProcessModal');
                loadProcesses();
            } else {
                throw new Error(result.error);
            }

        } catch (error) {
            showNotification('Error al crear proceso: ' + error.message, 'error');
        }
    };

    document.getElementById('deployForm').onsubmit = async function(e) {
        e.preventDefault();

        try {
            const response = await fetch(`/api/processes/${currentProcessId}/deploy`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    variables: document.getElementById('deployVariables').value,
                    simulation: document.getElementById('isSimulation').checked
                })
            });

            const result = await response.json();

            if (result.success) {
                showNotification('Proceso desplegado correctamente', 'success');
                closeModal('deployModal');
                loadTasks();
            } else {
                throw new Error(result.error);
            }

        } catch (error) {
            showNotification('Error al desplegar: ' + error.message, 'error');
        }
    };

    document.getElementById('simulationForm').onsubmit = async function(e) {
        e.preventDefault();

        try {
            const response = await fetch('/api/simulations', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    process_id: currentProcessId,
                    num_instances: document.getElementById('numInstances').value,
                    parameters: document.getElementById('simulationParams').value
                })
            });

            const result = await response.json();

            if (result.success) {
                showNotification('Simulación iniciada correctamente', 'success');
                closeModal('simulationModal');
                loadMetrics(currentProcessId);
            } else {
                throw new Error(result.error);
            }

        } catch (error) {
            showNotification('Error al ejecutar simulación: ' + error.message, 'error');
        }
    };

    document.getElementById('taskForm').onsubmit = async function(e) {
        e.preventDefault();

        try {
            const formData = new FormData(this);
            const formDataObj = {};

            for (let [key, value] of formData.entries()) {
                if (key !== 'comments') {
                    formDataObj[key] = value;
                }
            }

            const response = await fetch(`/api/tasks/${currentTaskId}/complete`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    form_data: JSON.stringify(formDataObj),
                    comments: document.getElementById('taskComments').value
                })
            });

            const result = await response.json();

            if (result.success) {
                showNotification('Tarea completada correctamente', 'success');
                closeModal('taskModal');
                loadTasks();
            } else {
                throw new Error(result.error);
            }

        } catch (error) {
            showNotification('Error al completar tarea: ' + error.message, 'error');
        }
    };

    // Cerrar modales al hacer clic fuera
    document.addEventListener('click', function(e) {
        if (e.target.classList.contains('modal')) {
            e.target.classList.remove('active');
        }
    });
</script>